UPDATE products SET
  description = 'Total Station Robotik Leica TS16 memberikan performa survei terdepan dengan akurasi angular 1" dan jarak 1mm + 1.5ppm. Dilengkapi dengan teknologi ATRplus untuk automatic target recognition dan AutoHeight untuk pengukuran tinggi otomatis tanpa reflector. Captivate software memberikan workflow yang intuitif, sedangkan PowerSearch memungkinkan pencarian target dalam radius 360°. Solusi ideal untuk survei konstruksi, monitoring struktur, as-built survey, dan pemetaan detail di proyek-proyek infrastruktur Indonesia.',
  meta_title = 'Leica TS16 Total Station Robotik Indonesia - Akurasi 1 Detik ATRplus Technology',
  meta_description = 'Leica TS16 Total Station Robotik Indonesia. Akurasi angular 1", ATRplus automatic tracking, AutoHeight technology. Distributor resmi dengan training operator dan support teknis.',
